REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
	(1, 'ruRU', 'Задание Канретада', 'C возвращением из мира смерти, герой. Было время, когда ты с гордостью $gстоял:стояла; среди своих собратьев, и меч твой был остер. Ныне же ты – лишь тень прошлого. Но встань передо мной, и я воскрешу легендарного рыцаря, которым ты некогда $gбыл:была;.$b$bЯ восполню твои силы, восстановлю оружие и подготовлю тебя к новым подвигам.', 'Поговорите с Канретадом, чтобы восстановить ваши таланты, оружие и средство передвижения.', '', 'Вернитесь к Канретаду.', 'Вспомните свои таланты', '', '', '', 0),
	(55, 'ruRU', 'Морбент Скверн', 'Морбент Скверн прячется в своем доме на вершине холма на востоке, рядом с кладбищем Вороньего холма. Пора положить конец его бесчинствам в наших землях...$B$BПримени против него Погибель Морбента, она обратит в прах всю его защитную магию.$b$bУбей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, герой Сумеречного леса.', 'Примените Погибель Морбента против Морбента Скверна, убейте его и верните Погибель Морбента в лагерь Свена.', '', 'Вернитесь к Свену Йоргену на Затихший берег, что в Сумеречном лесу.', 'Убейте Морбента Скверна', '', '', '', 0),
	(147, 'ruRU', 'Охота на человека', 'Если Вымогатель забирает золото с наших рудников, значит, он обворовывает королевство! Он должен предстать перед судом – а мне понадобится то кольцо, которое упоминалось в записке. Возможно, оно поможет нам узнать, на кого работает этот Вымогатель...$B$BЗдесь написано, что Вымогатель скрывается на тыквенном поле Бреквеллов. Попробуй поискать его там.', 'Найдите и убейте "Вымогателя", а затем принесите его кольцо маршалу Дугхан.', '', 'Вернитесь к маршалу Дугхан на лесопилку Восточной долины в Элвиннском лесу.', '', '', '', '', 18019),
	(192, 'ruRU', 'Охота на пантер', 'А теперь – самое трудное. Чем пантеры взрослее, тем хитрее. Они буквально сливаются с окружающей средой и их нелегко обнаружить. Этих хитрющих зверюг называют "тенебрюхими" за способность внезапно появляться из темноты... и набрасываться на добычу. А зубки у них о-го-го, можешь не сомневаться!$B$BЕсли хочешь, чтобы тебя признали $gнастоящим охотником:настоящей охотницей; на пантер, тебе нужно убить тенебрюхих пантер. А по-другому – никак. Эти животные встречаются на юго-востоке, за рекой.', 'Убейте 10 тенебрюхих пантер.', '', 'Вернитесь к сэру С. Дж. Эрлджедину в лагерь экспедиции Эрнестуэя в Северной Тернистой долине.', '', '', '', '', 0),
	(255, 'ruRU', 'Наемники', 'Пройдет два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да еще два месяца они будут до нас добираться! И мало того, что наш город остался без защиты, но раскоп и Дамба – Дамба! – тоже в опасности.$b$bПохоже, у меня нет выбора. Придется искать наемников.$b$bКак насчет тебя? На первый взгляд ты подходишь, |3-6($c). На северо-восточном берегу озера разбила лагерь группа огров. Может быть, ты избавишь наш город от опасности?', 'Келт Томасин из лагеря Мо\'грош просит вас убить 4 огров из клана Мо\'грош, 4 громил из клана Мо\'грош и 4 головорезов из клана Мо\'грош.', '', '', '', '', '', '', 0),
	(317, 'ruRU', 'Заготовка продовольствия', 'Я веду подготовку к выполнению боевого задания Осадной бригады. Дело будет долгим, и мне нужно укомплектовать мой паровик провизией на месяц. Так что пока Сталежар работает с моим танком, не отправишься ли ты на охоту?$B$BМне нужен мех, чтобы сделать кровать, и кабанина для еды. Кабаны – на мясо, медведи – на мех... Этих животных можно найти в снежных полях к югу от Серого логова.', 'Принесите 4 куска кабанины и 2 толстых медвежьих шкуры пилоту Толстопузу в Поселок Сталежара.', '', 'Вернитесь к пилоту Толстопузу в поселок Сталежара.', '', '', '', '', 18019),
	(376, 'ruRU', 'Проклятые', 'В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тени Сарвису, какая может потребоваться. $b$bПохоже, и ты будешь $gзаписан:записана; к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю. В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь. У меня заканчиваются запасы лап и крыльев, и если ты принесешь мне немного, я найду для тебя какой-нибудь доспех. К югу отсюда волков-падальщиков и летучих мышей предостаточно.', 'Ученице Элрет нужно 6 лапы падальщика и 6 крыла сумеречницы.', '', 'Вернитесь к новобранцу Элрет в Похоронный Звон, что в Тирисфальских лесах.', '', '', '', '', 0),
	(387, 'ruRU', 'Подавление бунта', 'Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда.$b$bНаказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдет в норму.', 'Тюремщик Телвотер просит вас убить в тюрьме 10 узников из Братства Справедливости, 8 каторжников из Братства Справедливости и 8 мятежников из Братства Справедливости.', '', 'Вернитесь к тюремщику Телвотеру в Штормград.', '', '', '', '', 0),
	(399, 'ruRU', 'Скромные дары прошлого', 'С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность. Говорят, нельзя вернуться в прошлое – и это верно. Дважды верно, если говорить обо мне – ведь мой родной дом был разграблен ворами и сожжен.$B$BЯ спросил у отца о судьбе некоторых моих вещей, например, о моем первом компасе. Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме.$B$BУсадьба Алекстона расположена к западу от Сторожевого холма. Может быть, ты найдешь мой компас?', 'Обыщите дом Бароса Алекстона в Западном Крае, найдите компас и вернитесь на Соборную площадь Штормграда.', '', 'Вернитесь к Баросу Алекстону в Штормград.', '', '', '', '', 0),
	(456, 'ruRU', 'Природное равновесие', 'Мои приветствия, $n. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. $b$bВесенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают.$b$bК несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. $gЮный:Юная:c; |3-6($c), помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.', 'Убейте 4 молодых ночных саблезубов и 4 молодых щетинистых вепрей.', '', 'Вернитесь к Опекуну Илталайну в Тенистую долину.', '', '', '', '', 0),
	(457, 'ruRU', 'Естественное равновесие', 'Истребление детенышей в Тенистой долине – хорошее начало, $n. Однако нас ждет еще много работы.$b$bЛесные ресурсы очень быстро подойдут к концу, если вовремя не устранить проблему. Уничтожение лесного зверья – вынужденное зло во имя блага всех тех, кто населяет эти места. Отправляйся на северо-восток вглубь Тенистой долины и истреби облезлых ночных саблезубов и щетинистых вепрей, чтобы восстановить естественное равновесие.', 'Опекун Илталайн хочет, чтобы вы убили 5 облезлых ночных саблезубов и 5 щетинистых вепрей.', '', 'Вернитесь к Опекуну Илталайну в Тенистую долину.', '', '', '', '', 0),
	(498, 'ruRU', 'Спасение', 'Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат.$b$bМы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать.$b$bДарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог\'тара, освободи их.', 'Освободите Друлла и Тог\'тара по поручению Круска с мельницы Таррен.', '', 'Вернитесь к Круску на Мельницу Таррен, что в Предгорьях Хилсбрада.', 'Освободите Друлла', 'Освободите Тог\'тара', '', '', 0),
	(532, 'ruRU', 'Битва за Хилсбрад', 'В Хилсбраде царит паника. Думаю, он скоро падет. Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки.$B$BНевзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия. Мы должны уничтожить их главу, мирового судью Бернсайда, и весь городской совет. Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации.', 'Убейте мирового судью Бернсайда, и 4 членов совета Хилсбрада. Уничтожьте Хилсбрадское официальное объявление. Украдите регистрационную книгу Хилсбрада. Возвращайтесь к Дарталии на мельницу Таррен.', '', 'Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.', '', '', 'Хилсбрадское официальное объявление уничтожено', '', 0),
	(553, 'ruRU', 'Месть Гелькулара', 'Вот, возьми Гелькуларов жезл. Он тебе понадобится.$B$BГелькулар создал для своего заклятья 3 церемониальных погребальных костра. Пламя Азеля и пламя Вераза находятся в Пещерах предгорий. Пламя Узеля находится в пещере выше по склону, в северной части гор.$B$BГелькуларов жезл необходимо зарядить в каждом из этих костров. Завершив ритуал, вонзи жезл в гробницу Гелькулара в Южнобережье, надежно охраняемом человеческом городе на юге. Мы отомстим!', 'Зарядите жезл Гелькулара силой пламени Азеля, пламени Вераза и пламени Узеля.$B$BВонзите заряженный жезл в гробницу Гелькулара в Южнобережье.', '', 'Разыщите могилу Гелькулара на Кладбище Южнобережья, что в Предгорьях Хилсбрада.', 'Сила пламени Азеля получена', 'Сила пламени Вераза получена', 'Сила пламени Узеля получена', '', 0),
	(633, 'ruRU', 'Мост Тандола', 'Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня $Gопечалил:опечалила;, $n.$b$bНо его жертва будет не напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с Нагорьем Арати.$b$bЕсли ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай все возможное, чтобы спасти мост Тандола, и возвращайся ко мне.$b$bТы – наша единственная надежда.', 'Уничтожьте взрывчатку.', '', 'Вернитесь к Рагу Гармасону в Дун Модр, что в Болотине.', 'Взрывчатка уничтожена', '', '', '', 0),
	(786, 'ruRU', 'Предотвращение агрессии племени Колкар', 'Говори потише, |3-6($c)! Кентавры из племени Колкар совсем близко, вон там, к западу от Утеса Колкара.$b$bПрошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!$b$bНельзя допустить, чтобы они это сделали! Достаточно ли ты $gхрабр:храбра;, чтобы напасть на Утес Колкар и уничтожить их планы?$b$bЯ заметил, что они хранятся у трех лидеров кентавров.', 'Лар Ночной Клык из деревни Сен\'джин хочет, чтобы вы уничтожили 3 плана нападения, которые хранятся в лагере кентавров, что на Утесе Колкар.', '', 'Вернитесь к Лару Ночному Клыку в Деревню Сен\'джин, что в Дуротаре.', 'План нападения на Долину Испытаний уничтожен', 'План нападения на деревню Сен\'джин уничтожен', 'План нападения на Оргриммар уничтожен', '', 0),
	(849, 'ruRU', 'Месть Ганна', 'Изучив схемы Хазгорма, можно без труда создать взрывчатку.$B$BНу вот, готово. $b$bА теперь, $n, я дам тебе особое задание. Возьми взрывчатку и подорви ветролет в Бейл Модане.$B$BЭта машина не просто играет ключевую роль в снабжении раскопок, она служит и для военных целей. И что еще важнее – она воплощение мощи дворфов и оскорбление памяти моего племени.$B$BВыполни это задание, и я буду гордиться тобой! Ну и награду ты тоже получишь.', 'Уничтожьте ветролет в Бейл Модане и возвращайтесь к Ганну Каменному Копью.', '', 'Вернитесь к Ганну Каменному Копью на Южный Золотой Путь, что в Степях.', 'Уничтожить ветролет в Бейл Модане', '', '', '', 0),
	(877, 'ruRU', 'Застывший оазис', 'Быть может, и в других оазисах Степей есть расселины вроде той, что тебе удалось обнаружить в Забытых прудах? Коли так, скорее всего именно эти расселины – источник жизни оазисов.$B$BНадо проверить.$B$BВот, возьми эти семена. Сейчас они мертвые и бесплодные. Отнеси их в Застывший оазис на юго-востоке. Если там есть расселина, помести в нее семена... и понаблюдай. О результатах нужно будет доложить Тонге в Перекресток.', 'Внимательно осмотрите Застывший оазис и возвращайтесь к Тонге Рунному Тотему в Перекресток.', '', 'Сообщите о своих находках Тонге Руническому Тотему. Его можно найти в Перекрестке, в Северных Степях.', 'Проверьте мертвые семена', '', '', '', 0),
	(900, 'ruRU', 'Самофланж', 'В настоящий момент открыты три контрольных клапана. Судя по надписям на панели управления, их надо закрыть, прежде чем выключать прибор.', 'Закройте топливный распределительный клапан, перепускной клапан и главный клапан управления, а потом снова попытайтесь воспользоваться панелью управления.', '', 'Вернитесь к панели управления, находящейся в исследовательском центре Торговой Компании в Северных Степях.', 'Перекройте главный клапан управления', 'Перекройте топливный распределительный клапан', 'Перекройте перепускной клапан', '', 0),
	(905, 'ruRU', 'Разъяренные смертехваты', 'Что ж, $n, твоя задача усложняется. Теперь тебе нужно сперва найти логово своей добычи, а затем победить ее прямо там.$B$BЯ предлагаю поохотиться на яркочешуйчатых ящеров. Их жилища располагаются к югу отсюда, среди холмов, сразу возле дороги. Убей их и собери их перья. Положи перья в гнезда яркочешуйчатых ящеров, чтобы показать их сородичам, что ты их не боишься!$b$bНо будь $gвнимателен:внимательна:c; |3-6($c). Ящеры охотятся стаями, они все набросятся на тебя, если ты не будешь достаточно $gосторожным:осторожной;.', 'Поохотьтесь на яркочешуйчатых ящеров и соберите с них перья. Отнесите перья в 3 гнезда когтедеров. Возвращайтесь к Сергре Черный Шип в Перекресток.', '', 'Вернитесь к Сергре Черный Шип в Перекресток в Северных Степях.', '', 'Посетите синее гнездо ящера', 'Посетите желтое гнездо ящера', 'Посетите красное гнездо ящера', 0),
	(916, 'ruRU', 'Яд чащобного паука', 'Я пришел в Тенистую долину, чтобы наблюдать за чащобными тенетниками, обитающими в Паучьем логове. Они – родичи более мелких разновидностей пауков. Полагаю, что Древо Жизни оказало на них сильное воздействие... Я хотел бы получить несколько вещей, чтобы изучить их и подтвердить свои догадки.$B$BДля начала мне понадобится немного их яда. Добудь ядовитые железы у пауков-тенетников в Паучьем логове и вокруг него, к северу отсюда. После этого я смогу изучить эти образцы и понять, есть ли у этого яда сходство с ядом их более мелких сородичей.', 'Принесите 10 ядовитых желез чащобных тенетников Гилшалану Буйному Ветру, стоящему у Альдрассила.', '', 'Вернитесь к Гилшалану Буйному Ветру, стоящему у Альдрассила.', '', '', '', '', 0),
	(919, 'ruRU', 'Ростки древесника', 'Вокруг вод озера Аль\'Амет прорастают маленькие древесники. Боюсь, им уже не помочь, нам придется выдернуть их из земли прежде, чем они станут слишком большими и начнут приносить беды.$B$BКогда будешь бродить вокруг озера, выдергивай каждый росток древесника, что попадется тебе по дороге. Помоги очистить нашу землю!', 'Принесите 10 ростков древесника.', '', 'Вернитесь к Деналану к озеру Аль\'Амет.', '', '', '', '', 18019),
	(924, 'ruRU', 'Демоново семя', 'Демоново семя – страшное оружие Пылающего Легиона. Оно хранится в пещере на Вершине Багрового Тумана, над демоническим алтарем Огня.$B$BЯ подготовил силовые камни, которые разорвут связь Семени с Легионом.$B$BВозьми камень со стола и возложи его на алтарь Огня на Вершине Багрового Тумана. Отправляйся на запад, а на развилке сверни на север. Вершина окажется по левую руку от тебя. Безопаснее всего подниматься по северному склону. $B$BТоропись: сила камня постепенно иссякает.', 'Возьмите треснувший камень силы, возложите его на алтарь Огня до окончания его действия и возвращайтесь к Ак\'Зелоту.', '', 'Вернитесь к Ак\'Зелоту в Степи.', 'Уничтожьте Демоново семя', '', '', '', 0),
	(945, 'ruRU', 'Спасение Терилун', 'Помогите!$b$bЯ бродила у Меча Властителя, как вдруг меня окружили эти жуткие сектанты. Счастье, что я умею отлично прятаться!!!$b$bМожете помочь мне отсюда выбраться? И еще, мне нужно будет сообщить моей сестре Тересиль, что я в порядке. Она в Ясеневом лесу, к югу отсюда, у святилища Эссины.', 'Помогите Терилун спастись, а потом сообщите Тересиль у святилища Эссины, что ее сестра в безопасности.', 'Помогите Терилун спастись из Меча Властителя.', '', '', '', '', '', 18019),
	(953, 'ruRU', 'Падение Амет\'Арана', 'К востоку отсюда находятся руины Амет\'Арана. Сейчас их населяют неупокоенные духи высокорожденных, некогда живших в его стенах, но когда-то Амет\'Аран был местом, где слуги Азшары свободно практиковались в своей могучей магии.$b$bМеня послали исследовать эти руины, и я наткнулась на две большие таблички, на которых была неразборчиво начертана история Амет\'Арана и его падения. Пока я пыталась прочесть руны, на меня напали призраки, и я сбежала.$b$bПожалуйста, если можете, отправляйтесь в руины и расшифруйте таблички вместо меня.', 'Изучите таблички, рассказывающие об Амет\'Аране и его падении, а затем возвращайтесь к часовому Тише Лунный Клинок, находящейся на Темных берегах.', '', '', 'Прочтите "Песнь об Амет\'Аране"', 'Прочтите "Падение Амет\'Арана"', '', '', 0),
	(957, 'ruRU', 'Башал\'Аран', 'Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорожденных. В Амет\'Аране – точно таких же руинах к югу отсюда – до сих пор горит древнее синее пламя. В этом огне печать может быть уничтожена.$b$bБудь осторожнее в тех руинах, $n...', 'Уничтожьте древнюю печать из лунного камня у древнего пламени в Амет\'Аране, затем вернитесь к Астериону в Башал\'Аран.', '', '', 'Уничтожьте печать у древнего пламени', '', '', '', 0),
	(974, 'ruRU', 'Найти источник', 'Эти горячие источники всегда были для меня загадкой! Откуда берется жар? $B$BЕсли учесть, что источники расположены совсем недалеко от Вулкана Огненного Венца, можно предположить, что их подогревает вулкан. Я разработал термометр, чтобы измерять температуру вулкана, и теперь хочу выяснить, в какой точке она наиболее высока. Термометр дает результаты по шкале Кракленгейта. $B$BВот, держи, отправляйся на хребет и выясни, где там точка с самой высокой температурой!', 'Выясните, где находится точка самой высокой температуры на Вулкане Огненного Венца, по просьбе Кракла из Кратера Ун\'Горо. $B$BДля измерения температуры щелкните по термометру правой кнопкой мыши. Проверяйте все горячие точки, пока не будет обнаружена точка с самой высокой температурой.', '', 'Вернитесь к Краклу на Горячие источники Голакка, что в Кратере Ун\'Горо.', 'Найдите самую горячую точку Вулкана Огненного Венца', '', '', '', 0),
	(1011, 'ruRU', 'Чума Отрекшихся', 'Отрекшиеся, нежить из Орды, проникли в Ясеневый лес, и рыщут среди развалин и курганов. Мы уверены, что их цель – распространить чуму по землям ночных эльфов. Мы должны убедиться в этом!$B$BОтрекшиеся разбили лагерь к югу отсюда, рядом с Обителью Дор\'Данил, где они готовят яды и заразу и разливают их по бутылкам. Проложи себе путь в этот лагерь и укради бутыль с заразой. Принеси ее сюда. Я исследую ее и узнаю, для чего она.', 'Принесите бутыль заразы Кайнету Штилю в Лесную Песнь.', '', '', '', '', '', '', 18019),
	(1022, 'ruRU', 'Воющая долина', 'Хотя мы затратили много средств и сил на то, чтобы вытеснить остатки демонов из Оскверненного леса на север, успехи наши невелики. Нам удалось не допустить большую часть демонов в Ясеневый лес.$b$bНа севере, у границы Оскверненного леса, разрушенное святилище Мел\'Тандрис захватили загадочные волколюди. Из-за их пронзительных воплей это место называют теперь Воющей долиной. Фолиант Мел\'Тандрис, что хранится в святилище может пролить свет на появление там волколюдей.', 'Отправляйтесь в Воющую долину, изучите фолиант Мел\'Тандрис, затем возвращайтесь к часовому Мелирии Ледяной Тени в Лесную Песнь.', '', '', 'Изучите фолиант Мел\'Тандрис', '', '', '', 0),
	(1025, 'ruRU', 'Лучшая защита – нападение', 'Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе еще одно поручение, прежде чем ты отправишься к лунному колодцу.$B$BНа дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращенный разум питается страхом, а кровожадность утоляется кровью невинных жертв.$B$BПомоги часовым защитить эти края, отплати этим чудовищам их же монетой.$B$BДумаю, их лагерь находится к югу от дороги... будь $Gосторожен:осторожна;.', 'Убейте 1 дозорного, 2 ведмедей, 10 тотемистов и 12 воинов из племени Гиблой Чащи, а затем вернитесь к Раэне Волкопас в Астранаар.', '', '', '', '', '', '', 18019),
	(1034, 'ruRU', 'Руины Звездной Пыли', 'Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже ее мучить, хвала богине. Но... лихорадка все еще сжигает ее.$B$BОрендил рассказал мне о морозной пыли, которую находят среди руин Звездной Пыли. Может, она усмирит лихорадку Релары. Собери немного этой пыли, прошу тебя, и принеси ее мне.$B$BРуины Звездной Пыли находятся на юге, $n. Да ускорит твой шаг Элуна!', 'Принесите 5 горстей звездной пыли Пельтуру в Астранаар.', '', '', '', '', '', '', 18019),
	(1035, 'ruRU', 'Зеркало Небес', 'Лихорадка Релары прошла, но она еще очень слаба. Я не верю, что только время вернет ей былую силу. Мне кажется, тут нужна мощь лунного камня.$B$BМы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники.$B$BИх предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты $Gдолжен:должна; отнять лунные камни у Оракула.$B$BИ, боюсь, для этого тебе придется его убить.', 'Отнимите лунный камень Упавшего Неба у Чащобного Оракула и принесите его Пельтуру в Астранаар.', '', '', '', '', '', '', 18019),
	(1043, 'ruRU', 'Коса Элуны', 'Кажется, ты говоришь правду... Я не до конца понимаю твои мотивы, но если ты $Gготов:готова; избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться. Важен результат.$b$bВоргены захватили рудник на юге. Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника.$b$bСтупай по своим делам, но если найдешь что-нибудь важное, расскажи об этом мне. Мы готовы принять любую помощь в нашей войне с силами зла.', 'Отыщите признаки местонахождения Косы Элуны и вернитесь к Джонатану Карвину в Темнолесье.', '', '', 'Найдите доказательство Косы Элуны', '', '', '', 0),
	(1134, 'ruRU', 'Величавые виверны Каменного Когтя', 'Между нами и Ордой война не объявлена, однако мир между нами очень хрупок. Мы часто обнаруживаем, что среди нас тайно действуют их агенты. $B$BОб одной такой операции мы узнали из скрытых источников в Тераморе. Эти источники утверждают, что орки собирают яд величавых виверн поблизости от Мутного Озера в Когтистых горах, на юге. А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса!$B$BЕсли это правда, мы обязаны остановить их, $n. Мы должны лишить их источника яда.', 'Принесите 12 ядовитых желез любой величавой виверны Шиндрелл Огненный Всполох в Астранаар.', '', '', '', '', '', '', 18019),
	(1140, 'ruRU', 'Башня Алталакса', 'Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. $b$bИз каракулей Илкруда можно понять, что у Атрикуса еще оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса.$b$bПоосторожнее там, $n, от вида кровавых храмов сатиров содрогнется даже $Gтакой закаленный:такая закаленная:c; |3-6($c), как ты.', 'Освободите заточенные души высокорожденных на Ночной поляне и Сатирнааре, затем вернитесь к Делгрену Очистителю на заставу Мейстры.', '', 'Вернитесь к Делгрену Очистителю на Заставу Мейстры, что в Ясеневом лесу.', 'Освободите душу высокорожденного на Ночной поляне', 'Освободите душу высокорожденного в Сатирнааре', '', '', 0),
	(1169, 'ruRU', 'Корни угрозы', 'Пока этот трусливый глупец Мок\'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает его власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас.$B$BПочему ты так озадаченно смотришь на меня, $n? $gДумал:Думала;, я буду говорить как неотесанный чурбан только потому, что я – огр?$b$bНо к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла.', 'Принесите Драз\'Зилбу в Деревню Гиблотопь 7 огненных языков и 7 пылающих сердец.', '', 'Вернитесь к Драз\'зилбу в деревню Гиблотопь, что в Пылевых топях.', '', '', '', '', 0),
	(1170, 'ruRU', 'Выводок Ониксии', 'Деревня Каменный Молот была захвачена выводком Ониксии. Но почему дочь великого дракона Смертокрыла вторглась в наши земли? Вот что тревожнее всего!$b$bНеужели только для того, чтобы уничтожить небольшое поселение огров?$b$bПредупреди Мок\'Морокка. Нельзя сидеть сложа руки!', 'Поговорите с властителем Мок\'Морокком в Деревне Гиблотопь.', '', '', '', '', '', '', 0),
	(1171, 'ruRU', 'Выводок Ониксии', 'Твоя уходить. Твоя идти и сказать Драз\'Зилбу, мы оставаться здесь. Здесь нет никакой черный дракон.', 'Поговорите с Драз\'Зилбом в Деревне Гиблотопь.', '', '', '', '', '', '', 0),
	(1172, 'ruRU', 'Выводок Ониксии', 'Потомки Ониксии распространились по всей Земле Драконов. Нельзя допустить, чтобы и остальные ее отродья вылупились на свет!$b$bПоспеши в Драконьи топи на юге Пылевых топей. Наверняка она устроила там свое логово. Найди яйца злой драконихи и уничтожь их!$b$bМы никогда не вернем себе деревню Каменного Молота, если вокруг будут продолжать плодиться драконы.$b$bА что касается Мок\'Морокка... касательно этого червя у меня есть особые планы.', 'Драз\'Зилб из Деревни Гиблотопь хочет, чтобы вы уничтожили 5 яиц Ониксии.', '', 'Вернитесь к Драз\'зилбу в деревню Гиблотопь, что в Пылевых топях.', 'Уничтожено яиц Ониксии', '', '', '', 0),
	(1173, 'ruRU', 'Вызов властителю Мок\'Морокку', 'Ты осмеливаешься вызвать на поединок властителя Мок\'Морокка?$b$bХа!$b$bМеня хочет сокрушить $Gжалкий:жалкая:r; |3-6($r)!$B$BПриготовишься к трепке – скажи мне.', 'Победите Мок\'Морокка и сообщите об этом Драз\'Зилбу в Деревне Гиблотопь.', 'Изгнать владыку Мок\'Морокка из Деревни Гиблотопь', 'Вернитесь к Драз\'зилбу в деревню Гиблотопь, что в Пылевых топях.', '', '', '', '', 0),
	(1200, 'ruRU', 'Злодейство в Непроглядной Пучине', 'Силы оставили меня. Мне необходима твоя помощь!$b$bВ давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный Лунный колодец.$b$bАку\'май, слуга Древнего бога, поднялся из глубин.$b$bСектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку\'май невинные жертвы.$b$bУбей Келриса и принеси его голову Сельгорму в Дарнасс,$n.', 'Принесите голову повелителя сумрака Келриса Рассветному дозорному Селгорму в Дарнасс.', '', '', '', '', '', '', 0),
	(1219, 'ruRU', 'Орочье донесение', 'Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. $B$BДонесение написано на орочьем... И по виду важное...', 'Доставьте орочье донесение лейтенанту Адену в Терамор.', '', '', '', '', '', '', 0),
	(1220, 'ruRU', 'Капитан Ваймс', 'Капитан Ваймс должен увидеть найденное тобой орочье донесение, $n. Он знает орочий язык, лучше чем кто либо из нас, и он должен быть осведомлен о том, что вблизи Терамора рыщут шпионы Орды.$b$bТы найдешь капитана в казармах в северо-восточной части острова Терамор.', 'Принесите шпионское донесение капитану Гаррану Ваймсу.', '', '', '', '', '', '', 0),
	(1251, 'ruRU', 'Черный щит', 'Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остове камина – только это и осталось от таверны "Последний привал".$b$bЩит можно снять.', 'Принесите почерневший железный щит Крогу в Деревню Гиблотопь.', '', '', '', '', '', '', 0),
	(1252, 'ruRU', 'Лейтенант Павал Рит', 'Солнечный зайчик блеснул в глаза из-под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$b$bПод якорем выбито имя владельца: "Лейтенант Павал Рит".', 'Принесите бляху Рита капитану Гаррану Ваймсу в Терамор.', '', '', '', '', '', '', 0),
	(1253, 'ruRU', 'Черный Щит', 'Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остатках камина – только это и осталось от таверны "Последний привал".$b$bЩит можно снять.', 'Принесите почерневший железный щит капитану Гаррану Ваймсу в Терамор.', '', '', '', '', '', '', 0),
	(1259, 'ruRU', 'Лейтенант Павал Рит', 'Лейтенант Павал Рит? Не припоминаю такого имени. Лучше всего вам будет поговорить с адъютантом Тезораном. У него хранятся все записи о тераморских стражниках – от их имен до предпочитаемого вооружения.$B$BУж он-то расскажет вам об этом Павале Рите.', 'Поговорите о Рите с адъютантом Тезораном в Тераморе.', '', '', '', '', '', '', 0),
	(1260, 'ruRU', 'Морган Штерн', 'Я составляю новое меню для ресторана. Сельская кухня с болотным душком. Думаю, посетителям "Печального отшельника" понравится!$b$bЯ послал своего племянника Моргана в Терамор, город на краю Пылевых топей. Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи.$b$bДолог путь до Терамора, и для меня тяжеловат. Но я думаю, что $Gтакой молодой:такая молодая:c; |3-6($c) с радостью ухватится за возможность совершить подобное путешествие.', 'Поговорите с Морганом Штерном в Тераморе.', '', '', '', '', '', '', 0),
	(1268, 'ruRU', 'Подозрительные следы копыт', 'Цепочка следов уходит от все еще дымящегося остова таверны "Последний привал". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.', 'Доложите о подозрительных следах возле таверны "Последний привал" Крогу из деревни Гиблотопь.', '', '', '', '', '', '', 0),
	(1269, 'ruRU', 'Лейтенант Павал Рит', 'Солнечный зайчик блеснул в глаза из под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$b$bПод якорем выбито имя владельца: "Лейтенант Павал Рит".', 'Принесите бляху Рита Крогу в деревню Гиблотопь.', '', '', '', '', '', '', 0),
	(1273, 'ruRU', 'Допрос Рита', 'Это было непросто, но я все-таки нашел этот Рит. Неплохо он прятаться... Для человек. $b$bОгрон боится, что человек свихнуться, – слишком много времени на болоте, Твоя идти с Огрон и спрашивать человека все, что хотеть.', 'Пойдите с Огроном и поговорите с Ритом, потом вернитесь к Крогу в Деревню Гиблотопь.', 'Вместе с Огроном допросите Рита.', 'Вернитесь к Крогу в Пылевые топи.', '', '', '', '', 0),
	(1276, 'ruRU', 'Черный щит', 'А, вспомнил! Мозарн – знаменитый кузнец из Громового Утеса. Я же помню, что слышал это имя прежде!$b$bЕсли мне не изменяет память, Служители Земли наградили меня оружием его работы, хорошее было оружие.$b$bВозможно, он расскажет тебе больше о щите, вышедшем из его рук.$b$bЯ не уверен, что эта информация важна, но, поскольку мы так и не знаем ничего о Рите, пренебрегать ей было бы неразумно.', 'Покажите потемневший железный щит Мозарну из Громового Утеса.', '', '', '', '', '', '', 0),
	(1282, 'ruRU', 'Зовут его Улыбка Джим', 'Ничего не могу с собой поделать, мне так жаль старину Джима... Он не всегда был таким... Когда-то он держал таверну на болотах, дивное было местечко.$b$bСлушай, я не в настроении говорить об этом. Если тебе нужна информация, поговори с капитаном Ваймсом. Он сидит на верхнем этаже в Цитадели, знаешь, эти большие казармы, к востоку от башни леди Джайны.', 'Поговорите с капитаном Гарраном Ваймсом на верхнем этаже Цитадели.', '', '', '', '', '', '', 0),
	(1284, 'ruRU', 'Подозрительные следы копыт', 'Цепочка следов уходит от все еще дымящегося остова таверны "Последний привал". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.', 'Доложите о подозрительных следах возле таверны "Последний привал" капитану Гаррану Ваймсу из Терамора.', '', '', '', '', '', '', 0),
	(1285, 'ruRU', 'Солдаты Даэлина', 'Реддон... Редпат... А! Вот он! Лейтененат Павал Рит.$b$bВсупил в ряды тераморской стражи вместе с остальными новобранцами, которые пришли из-за моря вместе с леди Праудмур. Зачислен в морские пехотинцы Кул-Тираса в возрасте шестнадцати лет. Отличная служба, поощрения...$b$bЧислится пропавшим без вести.', 'Вернитесь с информацией о Рите к капитану Гаррану Ваймсу в Терамор.', '', '', '', '', '', '', 0),
	(1286, 'ruRU', 'Дезертиры', 'Удержаться здесь, на болотах, было нелегко. Но, благодаря решимости и отваге, мы смогли возвести несколько оборонительных сторожевых башен в округе.$b$bПо последним донесениям наших разведчиков, группа дезертиров засела в Разрушенной башне, к юго-востоку от таверны. $B$BЗа главного у них, кажется, Балос Хакен. Посмотрим, может удастся получить от него какие-то сведения. $B$BНо будь с ним осторожнее, $n, он – тертый вояка.', 'Расспросите о Рите Балоса Хакена и его дезертиров в Пылевых топях.', '', '', '', '', '', '', 0),
	(1287, 'ruRU', 'Дезертиры', 'Рит? Этот трус?$b$bМы вышвырнули его из лагеря, потому что он настаивал на налете на деревню огров Гиблотопь, чтобы пограбить их запасы. Нас не так много, чтобы рассчитывать справиться с этими безмозглыми тварями. $b$bОн настолько часто зарывался, что мы решили, что с нас хватит, и прогнали его.$b$bВот, я помог тебе, почему бы теперь тебе не забыть о нашей встрече?', 'Поговорите о Рите с капитаном Гарраном Ваймсом в Тераморе.', '', '', '', '', '', '', 0),
	(1301, 'ruRU', 'Джеймс Хьяль', 'Перед тем, как перебраться сюда, в "Печальный отшельник", я обучался, у одного из лучших поваров которых я когда-либо встречал. Его звали Джеймс Хьяль, и все чего я добился в этой жизни, это только благодаря ему.$B$BИнтересно, как-то он там сейчас? Они вместе со своим братом Винсентом работали в таверне, в Гавани Менетилов, но я давно о нем ничего не слышал.$B$BЕсли вдруг ненароком встретишь его, кланяйся от меня.', 'Поговорите с Винсентом Хьялем в Гавани Менетилов.', '', '', '', '', '', '', 0),
	(1302, 'ruRU', 'Джеймс Хьяль', 'Мой брат Джеймс ушел за море с леди Праудмур. Последнее, что я слышал, было то, что по окончании боев он там открыл таверну. Но, где бы он ни находился, я уверен, что дела у него идут хорошо. Он ведь, знаете ли, великолепный повар.$b$bЯ некоторое время не имел о нем известий – видать, с таверной было много хлопот – но я уверен, что клерк в Тераморе сможет указать вам, где искать моего брата. Клерка вы найдете на верхнем этаже крепости в центре города, как же ее... А! Цитадель, вот как она называется.', 'Поговорите с клерком Лендри в Цитадели в Тераморе.', '', '', '', '', '', '', 0),
	(1319, 'ruRU', 'Черный Щит', 'Увы, но я не смогу помочь тебе, $n. Впрочем, я знаю, кто сможет. Каз Дваждыдвац – один из лучших наших кузнецов. Его можно найти на кузне.$b$bПокажи ему щит и послушай, что он скажет.', 'Покажите потемневший железный Щит Казу Дваждыдвацу из Терамора.', '', '', '', '', '', '', 0),
	(1320, 'ruRU', 'Черный Щит', 'Чуть было не просмотрел... Кожаный ремень на тыльной стороне щита сгорел, но, сдается мне, он был приспособлен под крупную руку. Скорее всего, тауренскую.$b$bВот, в общем, и все, что я могу тебе сказать. Передай капитану Ваймсу, что я сожалею, но больше ничем не могу ему помочь.', 'Поговорите с капитаном Гарраном Ваймсом в Тераморе.', '', '', '', '', '', '', 0),
	(1321, 'ruRU', 'Черный щит', 'Хмм... Я не вижу в этом щите ничего необычного. Нужно попросить До\'гола, нашего кузнеца, взглянуть на него. Может быть, До\'гол сможет рассказать нам больше, хотя я бы не надеялся на это...', 'Покажите потемневший железный щит До\'голу из Деревни Гиблотопь.', '', '', '', '', '', '', 0),
	(1322, 'ruRU', 'Черный щит', 'Хммм... Тут, на ободе щита, оказывается, есть надпись, но прочитать ее трудно, она почти вся обгорела.$b$bМне нужна кислота, чтобы слегка отчистить ее. Яд пауков Мглистой пещеры подойдет. Эти пауки водятся в старых копях – Мглистой пещере к северо-западу от деревни. Принеси мне немного их ядовитых желез, и я смогу отчистить этот щит.', 'Добудьте 5 ядовитых желез Паука Черного Тумана для До\'гола из Деревни Гиблотопь.', '', 'Вернитесь к До\'голу в деревню Гиблотопь, что в Пылевых топях.', '', '', '', '', 0),
	(1323, 'ruRU', 'Черный щит', 'Сдается мне, что с кислотой я переборщил. Теперь осторожно потрем щит...$b$bХмм. Прочесть сложновато, но, похоже, тут написано имя: Мозарн. Никогда о таком не слышал. Надо спросить Крога, он знаком с кучей народу.', 'Поговорите с Крогом в Деревне Гиблотопь.', '', '', '', '', '', '', 0),
	(1369, 'ruRU', 'Россыпи Слез', 'Племя Гелкис считает, что нас защищает матерь кентавров Терадрас. Они глупы. Кентавров никто не защищает. Маграм не нужна защита! Мы сильнее всех!$B$BПусть племя Гелкис поймет, насколько они глупы. Отправляйся в их деревню, прямиком к пещере. В этой пещере они хранят кристаллы – слезы Терадрас. Уничтожь эти кристаллы! Принеси мне их осколки!', 'Для поддержания отношений с племенем Маграм принесите 3 кристалла Россыпи Слез Варугу в деревню Маграм.', '', 'Вернитесь к Варугу в деревню Маграм, что в Пустошах.', 'Россыпи Слез', '', '', '', 0),
	(1657, 'ruRU', 'Чем пахнет в Южнобережье', 'Сделайте ваш праздник Тыквовина незабываемым... насолив нашим врагам на Южнобережье!$B$BВозьмите специально собранную бомбу-вонючку – она наполнена невероятно зловонным веществом, запах которого не вынесет ни одно тупое животное, включая людей. Вам нужно будет бросить ее в самый центр Южнобережья, так что готовьтесь к драке с Альянсом!$B$BА когда сделаете этот шаг к нашему освобождению, возвращайтесь ко мне!', 'Бросьте три бомбы-вонючки Отрекшихся в центр Южнобережья в Хилсбраде и вернитесь к призывательнице тьмы Янке на фестиваль Плетеного человека в Тирисфальских лесах.', '', 'Вернитесь к зовущей Тьму Янке на Руины Лордерона, что в Тирисфальских лесах.', 'Бросьте бомбу-вонючку в Южнобережье', '', '', '', 0),
	(1884, 'ruRU', 'Груды джуджу', 'Оказывается, нормальное течение магической энергии в Дуротаре нарушил чернокнижник Залазан с островов Эха. Для этого он разместил оскверненные фетиши, груды джуджу, среди домов центрального острова Эха.$b$bИз-за этого болеет здешнее зверье, а чернокнижники и пришельцы из преисподней, таящиеся во тьме, набираются силы.$b$bНеобходимо уничтожить эти груды джуджу, $n, прежде чем наши земли изменятся до неузнаваемости.', 'Уничтожьте 4 груды джуджу и вернитесь к Ун\'Туве из деревни Сен\'джин.', '', 'Вернитесь к Ун\'туве в деревню Сен\'джин.', 'Уничтожено груд джуджу', '', '', '', 0),
	(2078, 'ruRU', 'Месть Гиромачта', 'Эй, сухопутное создание, нужно, чтоб ты $gнашел:нашла; моего первого помощника.$B$BБерешь этот ключ, вставляешь ему в башку и ведешь сюда, чтобы он опять служил своему кэпу.$B$BЭтим мурлокам и их главарю не шибко понравится, когда ими займется мой первый помощник!', 'Найдите первого помощника Гелхака, Бешенатора 4100, и отведите его к Гелхаку.', '', '', 'Первый помощник Гелхака', '', '', '', 0),
	(2118, 'ruRU', 'Зачумленные земли', 'Болезнь расползается по Темным берегам, захватывая сознания и тела всех, до кого добирается.$B$BНа медведей-осотников она подействовала особенно жестоко. Некогда благородные звери стали инструментами разрушения, бешеными и неистовыми. Возможно, у меня есть средство от этой напасти.$B$BОтнеси в лес эту ловушку и положи ее на землю. Любой бешеный колючешерстный медведь, попавший в нее, станет на короткий период времени послушным. В таком состоянии он будет следовать за тобой. Приведи его сюда, $n.', 'Поймайте бешеного колючешерстного медведя отведите его Тарнариуну.$B$BЕсли вам не удастся поймать зверя и вы потеряете ловушку, вернитесь к Тарнариуну Целителю Деревьев и попросите у него еще одну.', '', '', 'Поймано бешеных колючешерстных медведей', '', '', '', 0),
	(2681, 'ruRU', 'Камни, что связывают нас', 'Одних лишь твоих сил не хватит, чтобы одолеть Разелиха и его приспешников.$B$BСобери подходящую группу искателей приключений и освободи моих подчиненных от вечных мук! Тебе нужно разбить восемнадцать камней.$B$BСражайся отважно и умри с честью, $n.', 'Освободите девять Слуг Разелиха, трех Слуг Севины, трех Слуг Аллистария и трех Слуг Грола. Когда ваша задача будет выполнена, возвращайтесь к павшему герою. Вы должны оставаться поблизости от камней, иначе процесс не будет завершен.', '', 'Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.', 'Освобождено слуг Разелиха', 'Освобождено слуг Гролла', 'Освобождено слуг Аллистария', 'Освобождено слуг Севины', 0),
	(2988, 'ruRU', 'Тролльи клетки', 'Пропал сын нашего самого лучшего грифона! Наследник Быстрокрыла, Остроклюв, пропал несколько дней назад, когда охотился вместе с родителями. Я думаю, его похитили тролли!$B$BПомогите нам! Остроклюва могут держать в клетке в одной из двух деревенек Сухокожих.', 'Проверьте клетки в двух деревнях Сухокожих и возвращайтесь к дрессировщику грифонов Разящему Когтю.', '', 'Вернитесь к укротителю грифонов Разящему Когтю на Заоблачный пик, что во Внутренних землях.', 'Проверьте первую клетку', 'Проверьте вторую клетку', 'Проверьте третью клетку', '', 0),
	(2994, 'ruRU', 'Спасение Остроклюва', 'Мы должны спасти Остроклюва!$B$BПробейтесь в верхнюю часть Джинта\'Алора, отберите ключ у коварной жрицы Ведьмисы, а потом найдите и освободите Остроклюва!', 'Пробейтесь в верхнюю часть Джинта\'Алора, убейте коварную жрицу Ведьмису, возьмите у нее ключ от клетки и освободите Остроклюва.', '', 'Вернитесь к укротителю грифонов Разящему Когтю на Заоблачный пик, что во Внутренних землях.', '', 'Откройте клетку Остроклюва', '', '', 0),
	(2995, 'ruRU', 'Линии связи', 'Сторожка Кель\'Данил – центр сообщения высших эльфов Внутренних земель. Их посланники пытаются установить отношения с другими расами и делятся с ними сведениями о троллях из племени Сухокожих, обитающих в южной части Внутренних земель. Все документы, связанные с этим, хранятся в сторожке.$b$bМы не хотим, чтобы Высокодолье заключало союзы с другими народами, $n.$B$BУничтожь документы Высокодолья. Есть мнение, что рукописи не горят... у тебя есть шанс проверить, так ли это.', 'Оран Змеиные Кольца из Подгорода просит вас отправиться во Внутренние земли и сжечь отчет Высокодолья, заметки Высокодолья и записи Высокодолья.', '', 'Вернитесь к Оран Змеиные Кольца в деревню Сломанного Клыка, что во Внутренних землях.', 'Сожгите записи Высокодолья', 'Сожгите заметки Высокодолья', 'Сожгите отчет Высокодолья', '', 0),
	(3042, 'ruRU', 'Троллье месиво', 'Тролли племени Песчаной Бури в Зул\'Фарраке делают состав для закалки из песчаника, и я бы не отказался заполучить себе немного этого состава. Он весьма ценится мастерами, так что если ты принесешь мне достаточно, то и вознаграждение будет щедрым.$B$BЗул\'Фаррак находится к северо-западу от Прибамбасска. Удачи!', 'Принесите 20 фиалов с Тролльим месивом.', '', 'Вернитесь к Трентону Молоту Света в Танарис.', '', '', '', '', 0),
	(3463, 'ruRU', 'Задай им жару!', 'Слушай меня внимательно, $n. Четыре башни нельзя разрушить, но если поджечь их с помощью факела воздаяния, пламя не угаснет очень долго – и это пламя нельзя будет унять никакими силами. $B$BПока башни горят, ни один страж или караульный не сможет подняться на них – а значит, первая линия обороны противника фактически будет прорвана. $B$BТы $gдолжен:должна; пробраться в башни и поджечь их с помощью факела воздаяния. И берегись патрульных Черного Железа!', 'Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния.', '', 'Вернитесь к оруженосцу Малтрейку в Тлеющее ущелье.', 'Западная башня подожжена', 'Южная башня подожжена', 'Восточная башня подожжена', 'Северная башня подожжена', 0),
	(3520, 'ruRU', 'Духи крикунов', 'Мне нужны духи дольных крикунов из Фераласа. Они родственники старого-престарого бога и напрямую связаны с ним.$b$bВозьми ежевичный посох и ступай в Фералас. Отыщи в южной и центральной части дольных крикунов и одержи над ними верх. Потом помаши моим посохом над их телами. Таким образом ты выманишь их души. Коснись каждой из душ и собери их сущности.$b$bПринеси мне посох и собранные сущности, и я расскажу тебе о том древнем боге.', 'Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе\'кинье в Порт Картеля.', '', 'Вернитесь к Йе\'кинье в Порт Хитрой Шестеренки, что в Танарисе.', 'Поймано душ крикунов', '', '', '', 0),
	(3521, 'ruRU', 'Противоядие для Иверрона', 'Мы могли бы помочь Иверрону: я знаю противоядие, которое нейтрализует действие яда. Но для него мне нужны некоторые ингредиенты.$B$BМне понадобятся гиацинтовые грибы. Их можно найти под деревьями или добыть у греллей к югу отсюда – похоже, они им по вкусу. Еще мне нужны лунные лилии, что растут только вокруг прудов.$B$BПоследний ингредиент добыть сложнее всего. Это лимфа тех самых чащобных тенетников, что отравили Иверрона.', 'Соберите 7 гиацинтовых грибов, 4 лунные лилии и 1 порцию лимфы чащобного тенетника и принесите Дирании Серебряное Сияние в Тенистую долину.', '', 'Найди Иверрона возле Паучьего логова.', '', '', '', '', 0),
	(3701, 'ruRU', 'Дымящиеся руины Тауриссана', 'Отправляйтесь в дымящиеся руины Тауриссана в Пылающих степях и соберите как можно больше информации.$B$BГоворят, все руины просто усыпаны таинственными реликвиями. Возможно, вам надо начать поиски здесь, $n. Опасайтесь таурисанских стражей-убийц, что стерегут руины, охраняя все тайны, какие там могут быть.', 'Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону.', '', 'Вернитесь к королевскому историку Аркессон к Высокому трону, что в Стальгорне.', 'Информация получена', '', '', '', 0),
	(3825, 'ruRU', 'Голова огра на палочке = вечеринка', 'Осталось только одно задание, солдат.$b$bЯ позволил себе вольность – нанизал голову Гор\'теша на пику. Тебе остается отнести ее на вершину скалы Молота Ужаса и воткнуть в землю. Стоит только сделать это, как трусливые огры бросятся куда глаза глядят! Когда ты повеселишься от души, возвращайся ко мне, и я награжу тебя за проделанную работу.$b$b*Кажется, Орелий теряет связь с реальностью.*', 'Отнесите голову Гор\'теша на вершину скалы Молота Ужаса. Поищите кучу рыхлой земли и воткните в нее пику.', '', 'Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.', 'Голова Гор\'теша установлена', '', '', '', 0),
	(3901, 'ruRU', 'Игрушки-погремушки', 'Ты уже $Gпродемонстрировал:продемонстрировала; свой потенциал в обычных обстоятельствах, $n, а теперь давай посмотрим, как ты будешь действовать под давлением.$B$BСкелеты-костетрясы – еще одни безмозглые приспешники Короля-лича – более серьезные враги, чем зомби, с которыми ты $Gсталкивался:сталкивалась; до этого. Я попрошу тебя уменьшить их количество и проявить себя среди Отрекшихся. Не мешкай! Когда все будет сделано – возвращайся ко мне.', 'Убейте 8 скелетов-костетрясов, а затем вернитесь к жрецу Тьмы Сарвису в Могильник.', '', 'Вернитесь к жрецу Тени Сарвису в Похоронный Звон, что в Тирисфальских лесах.', '', '', '', '', 0),
	(4921, 'ruRU', 'Пропавшая без вести', 'Мы бились в маленьком лагере тауренов и разделились в бою – на нее наседали разом трое дыбогривов. Силы были неравны. Я отвлек на себя очень многих и увидел, что набежали новые враги и одолевают ее. Впав в ярость, я бросился на врагов, но они с легкостью одержали надо мной верх.$B$BЯ пришел в себя и увидел, что таурен-друид ухаживает за мной, – он набрел на меня на Золотом пути.$B$BПрошу тебя, |3-6($c), узнай что-нибудь о моей жене.', 'Отыщите жену Манкрика и возвращайтесь к нему в Перекресток.', '', '', 'Найдите жену Манкрика', '', '', '', 0),
	(5097, 'ruRU', 'Сторожевые башни', 'Мы можем пометить будущие цели для наших войск при помощи магического устройства, сигнального факела. Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками.$b$bТвоя цель – ворваться в Андорал и установить сигнальные факелы на всех четырех башнях. Устанавливать факелы надо в дверных проемах; они сами собой отметят всю башню. В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну.', 'Отметьте все башни Андорала при помощи сигнального факела; запалить факел можно, находясь в дверном проеме каждой из башен.$b$bОтметив все четыре башни, верните сигнальный факел командиру Ашламу Неутомимому из лагеря Промозглого Ветра в Западных Чумных землях.', '', 'Вернитесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра, что в Западных Чумных землях.', 'Первая башня отмечена', 'Вторая башня отмечена', 'Третья башня отмечена', 'Четвёртая башня отмечена', 0),
	(5098, 'ruRU', 'Сторожевые башни', 'Мы можем пометить будущие цели для наших войск при помощи магического устройства, сигнального факела. Мы подозреваем, что Плеть пользуется сторожевыми башнями Андорала для управления собственными войсками.$b$bТвоя цель – ворваться в Андорал и установить сигнальные факелы на всех четырех башнях. Устанавливать факелы надо в дверных проемах; они сами отметят всю башню. В сигнальном факеле всего пять зарядов, поэтому не трать их понапрасну.', 'Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен.$b$bОтметив все четыре башни, следует вернуть сигнальный факел верховному палачу Деррингтону в Бастион в Западных Чумных землях.', '', 'Вернитесь к верховному палачу Деррингтону в Бастион, что в Тирисфальских лесах.', 'Первая башня отмечена', 'Вторая башня отмечена', 'Третья башня отмечена', 'Четвёртая башня отмечена', 0),
	(5163, 'ruRU', 'Йети где-то рядом...', 'Все готово, $n!$b$bИтак, я уже сообщила по почте моим друзьям, что у меня для них сюрприз. И тут на сцену выходишь ты!$b$bЯ дам тебе моего механического йети, а тебе нужно будет удивить их, нанеся визит каждому, включив йети и послав его по направлению к ним.$b$bКогда покажешь мое изделие Легакки в Круговзоре, Поливалке в Прибамбасске и Квикксилю в Укрытии Маршалла, возвращайся и расскажи мне, как все было!$b$bИ моего йети тоже, пожалуйста, приведи обратно.', 'Возьмите механического йети Уми и напугайте им ее друзей:$B$B- Легакки в Круговзоре (Зимние Ключи), $B- Поливалку в Прибамбасске (Танарис), $B- Квикксиля в Укрытии Маршалла (Кратер Ун\'Горо)$B$BКогда проделаете все это, принесите механического йети обратно Уми.', '', 'Вернитесь к Уми Румпельшникер в Круговзор, что в Зимних Ключах.', 'Напугайте Легакки', 'Напугайте Поливалку', 'Напугайте Квикксиля', '', 0),
	(5165, 'ruRU', 'Погасить Пламя Защиты', 'Теперь тебе надо вернуться в Джеденар. Эти жаровни скорее всего расставлены в Оплоте Теней. Загаси их пламя, и защита, возведенная Советом, хотя бы на некоторое время падет. Я буду ждать этого мгновения. Когда оно настанет, я загляну в недра оплота и попытаюсь узнать, кто стоит во главе всего этого. Тогда – и только тогда – мы попытаемся атаковать их напрямую.', 'При помощи очищенной воды Лунного колодца загасите пламя в четырех жаровнях защиты внутри Оплота Теней в Оскверненном лесу. Затем возвращайтесь к Грете Замшелому Копыту в Изумрудное святилище.', '', 'Вернитесь к Грете Замшелому Копыту в Изумрудное святилище, что в Оскверненном лесу.', 'Погасите жаровню Боли', 'Погасите жаровню Злобы', 'Погасите жаровню Страдания', 'Погасите жаровню Ненависти', 0),
	(5211, 'ruRU', 'Защитники Дарроушира', 'Многие защищавшие Дарроушир пали в битве. И многие из них восстали из мертвых, примкнув к Плети! Ты $gдолжен:должна; отыскать эти несчастные души и избавить их от страданий.$B$BКаннибалы-вурдалаки, бормочущие вурдалаки, болезненные живодеры – многие из них были добрыми жителями Дарроушира. Уничтожив их тела, ты освободишь их души.$B$BТы найдешь их в Чумном лесу, Перекрестке Корина и прочих опорных пунктах Плети в Восточных Чумных землях.', 'Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.', '', 'Вернитесь к Карлину Редпату в Часовню Последней Надежды, что в Восточных Чумных землях.', 'Освобождено духов Дарроушира', '', '', '', 0),
	(5245, 'ruRU', 'Беспокойные духи Кел\'Терила', 'Несчастные существа эти духи высокорожденных, что и говорить. Они всё ещё ищут части той вещи, которая навсегда привязала их к Кел\'Терилу, эту похищенную у них реликвию.$B$BЕсли тебе это интересно, можешь взять мою кирку и отправляться на юг к озеру, чтобы попытаться достать части этого артефакта изо льда.$B$BЯ не могу сказать что именно ты найдешь, но Аврора Зов Небес наверняка сможет; она живет около башни Северного Перевала в северной части Восточных Чумных земель.', 'Используйте кирку Джерона, чтобы добыть фрагменты реликвии высокорожденных, Принесите их Авроре Зову Небес в Восточные Чумные земли.', '', 'Принесите фрагменты реликвии высокорожденных Авроре Зову Небес в Восточные Чумные земли.', '', '', '', '', 0),
	(5251, 'ruRU', 'Архивариус', 'Впадать в крайности всегда опасно, $n. Взять, к примеру, Алый орден. Неужели такой слепой фанатизм способен привести к чему-то хорошему? Скольких невинных убили они во имя Света.$B$BЭто просто святотатство!$B$BВот что, один из этих негодяев мне особенно интересен – это архивариус Галфорд из Стратхольма. Этот человек отвечает за самые ценные документы ордена. Уничтожь его и сожги его архивы! Если справишься с этим, получишь достойную награду.', 'Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алого ордена.', '', 'Вернитесь к герцогу Николасу Зверенхоффу в Часовню Последней Надежды, что в Восточных Чумных землях.', '', 'Архив сожжен', '', '', 0),
	(5282, 'ruRU', 'Мятущиеся души', 'Только безграничная ненависть к Плети поддерживает во мне силы и желание жить. Но я не фанатик. Не такой, как этот сброд из Алого ордена – они скорее убьют невинную нежить, чем удостоят хоть каплей сочувствия.$B$BВозьми мой излучатель. С его помощью ты сможешь освободить истерзанные души, обреченные на скитания в Стратхольме.$B$BСтреляй в призраков, бродящих по улицам. Освободи их!', 'Стреляйте в призрачных и неупокоенных горожан на улицах Стратхольма из бластера Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.$B$BОсвободите 15 неупокоенных душ и возвращайтесь к Эгану.', '', 'Вернитесь к Эгану в Чумной лес, что в Восточных Чумных землях.', 'Освобождено душ', '', '', '', 0),
	(5382, 'ruRU', 'Доктор Теолен Крастинов – Мясник', 'Крастинов виновен в тысячах смертей. Справедливость должна восторжествовать – пусть он вкусит собственного блюда.$b$bНайди его и заставь испытать мучения его бессчетных жертв. Когда он умрет, сожги наши останки. Пусть обратятся в пепел, $n.', 'Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.', '', 'Вернитесь к Еве Саркофф на озеро Дарроумир, что в Западных Чумных землях.', '', 'Останки Евы Саркофф сожжены', 'Останки Люсьена Саркоффа сожжены', '', 0),
	(5441, 'ruRU', 'Ленивые батраки', 'Проклятые батраки! Им велено валить лес, но они все время пытаются отлынивать. Мне нужен кто-то, кто их приструнит. Ты, |3-6($r), мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум! Управишься – не забудь вернуть дубинку.$b$bПроклятые лентяи...', 'Проучите ленивых батраков дубинкой старшины. Разбудите 5 батраков, потом верните дубинку штейгеру Тазз\'рилу в Долине Испытаний.', '', 'Вернитесь к штейгеру Тазз\'рилу в Дуротар.', 'Проучено батраков', '', '', '', 0),
	(5561, 'ruRU', 'Отлов кодо', 'Гоблин Биббли считает, что только он и умеет делать деньги в Пустошах. Ха! Единственный караван, который не боится идти через эти края, полностью зависит от меня. С тех пор как я научился омолаживать кодо и управлять старыми и умирающими зверями с помощью моего энергетического инкапсулятора, мы трое – я, караванщик Корк и Риггер – создали что-то вроде компании.$B$BВот, держи инкапсулятор: он действует на древних или старых кодо. Они сразу становятся ручными и следуют за тобой. А дальше все просто: приручишь кодо – веди его ко мне.', 'Приведите пять прирученных кодо Смиду Заржавеню в лагерь Заржавня. Не забудьте вернуть ему энергетический инкапсулятор.', '', '', 'Приручено Кодо', '', '', '', 0),
	(5581, 'ruRU', 'Порталы Легиона', 'Вот тебе Рука Ируксоса.$B$BЯ самолично добыл ее у одного из вождей Пылающего Клинка.$B$BЕсли ты возьмешься закрыть порталы демонов на поле Маннорок – а именно об этом я и хочу тебя попросить, – она тебе пригодится.$B$BУгроза от демонов с каждым днем все серьезнее. Нужно закрыть порталы, чтобы прекратить их нашествие в наш мир.', 'Закройте 6 порталов на поле Маннорок, а затем вернитесь к Тайге Мудрой Гриве в Деревню Ночных Охотников.', '', '', 'Порталы закрыты', '', '', '', 0),
	(5621, 'ruRU', 'Облачение Луны', 'Мне нужна твоя помощь, $n. Я должна оставаться здесь, чтобы обучать других, но ты $Gмог бы:могла бы; помочь одной из наших раненых часовых к югу от Доланаара. Ее ранили, когда она патрулировала город, и ей нужна наша помощь. Ее зовут Шайя.$B$BКогда найдешь ее, исцели ее раны и укрепи ее тело заклятиями. По крайней мере, это защитит ее от бед на некоторое время. Когда выполнишь свой долг перед Элуной, возвращайся ко мне.', 'Найдите стража Шайю и исцелите ее раны при помощи малого исцеления (ранг 2). Потом скажите ей Слово силы: "Стойкость". Затем вернитесь к Лорне Утреннему Свету в Доланаар.', '', 'Вернитесь к Лорне Утреннему Свету на озеро Аль\'Амет, что в Тельдрассиле.', 'Исцелите стража Шайю и укрепите его здоровье', '', '', '', 0),
	(5624, 'ruRU', 'Облачение Света', 'Обычно я подвергаю всех последователей Света небольшому испытанию. Так я выясняю, достойны ли они своего первого облачения – символа того, что церковь их принимает и поддерживает.$B$BНо сейчас ситуация немного отличается. Один из жителей Златоземья видел раненого стража на берегу озера к востоку отсюда. Этого стража зовут Робертс. Найди его, исцели его раны, придай ему стойкости и вернись сюда. Если ты справишься, я сочту твое испытание завершенным.', 'Разыщите стражника Робертса и исцелите его раны, пользуясь "Малым исцелением" (уровень 2), а затем одарите его заклинанием "Слово силы: Стойкость", после чего вернитесь в Златоземье к жрице Жозетте.', '', 'Вернитесь к жрице Жозетте в Элвиннский лес.', 'Исцелите стражника Робертса и укрепите его здоровье', '', '', '', 0),
	(5625, 'ruRU', 'Облачение Света', 'Как правило, примерно в эту пору $gпослушники:послушницы; вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе. Но, честно говоря, сейчас у меня есть и более важные дела. Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф.$B$BИзлечи Дольфа и наложи на него "Слово Силы: Стойкость", и я сочту, что ты $Gпрошел:прошла; испытание. Справишься?', 'Найдите горного пехотинца Дольфа и исцелите его раны при помощи Малого исцеления (ранг 2). Также наложите на него "Слово силы: Стойкость", а затем вернитесь к Максану Ковальне в Каранос.', '', 'Вернитесь к Максану Анволу на Мерцающий хребет, что в Дун Мороге.', 'Исцелите горного пехотинца Дольфа и укрепите его здоровье', '', '', '', 0),
	(5648, 'ruRU', 'Одеяния духовности', 'Что ж, $n, вот ты и $gготов:готова; к своему первому испытанию. К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда. Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас. Ее зовут Корджа. Найди ее, исцели и дай ей благословение наших предков.$b$bСделай это – и я сочту, что ты $gподтвердил:подтвердила; свою готовность ступить на путь жреца.', 'Найдите рубаку Кор\'жу и исцелите ее раны, пользуясь Малым исцелением (уровень 2). Затем скажите ей Слово силы: Стойкость – и вернитесь к Тай\'джин в Колючий Холм.', '', 'Вернитесь к Тай\'джин в Колючий Холм, что в Дуротаре.', 'Исцелите стража Корджу и укрепите ее здоровье', '', '', '', 0),
	(5650, 'ruRU', 'Одеяния Тьмы', 'Мы черпаем силу из тьмы и теней, $n, но ваше дело – не только дело тьмы. Вы поняли, что большая заслуга есть и в изучении искусства лечения. Это мудрый выбор. Но прежде чем познать тьму, вы должны познать и свет, а для этого нужно пройти испытание.$B$BК северу от кладбища находится раненый страж смерти по имени Кел – он защищал нас от гноллов, и ему требуется лечение. Но для того чтобы он мог и дальше исполнять свой долг, вы должны также придать ему сил. Используйте для этого свои заклинания, а потом возвращайтесь ко мне.', 'Найдите стража смерти Кела и вылечите его раны заклинанием "Малое Исцеление" (ранг 2). После этого прочтите над ним "Слово Силы: Стойкость", а затем вернитесь к темному священнику Берилу в Брилл.', '', 'Вернитесь к темному священнику Берилу в Брилл, что в Тирисфальских лесах.', 'Исцелите стража смерти Кела и укрепите его здоровье', '', '', '', 0),
	(5721, 'ruRU', 'Битва при Дарроушире', 'Теперь, $n, тебе предстоит принять участие в битве при Дарроушире и спасти Джозефа Редпата.$B$BПоложи реликвии на городскую площадь Дарроушира, и духи его жителей восстанут из могил. Начнется битва, и ты $gдолжен:должна; сделать все возможное, чтобы Дейвил выжил в битве с Хоргусом, а Редпат должен подвергнуться порче и после этого быть убитым.$B$BВ этом случае дух Редпата будет спасен. Поговори с ним и возвращайся к его дочери Памеле.', 'Положите сверток с реликвиями на городской площади Дарроушира.$B$BОберегайте Дейвила Яркосвета, пока не погибнет Хоргус.$B$BНе допустите смерти капитана Редпата до появления Редпата Падшего. $B$BУбейте Редпата Падшего. $B$BПоговорите с духом Джозефа Редпата, когда он вновь появится на городской площади, затем отправляйтесь к Памеле и поговорите с ней.', '', 'Вернитесь к Памеле Редпат в Дарроушир, что в Восточных Чумных землях.', 'Примите покаяние Редпата', '', '', '', 0),
	(6041, 'ruRU', 'Дымок над водою', 'Пока ты $gзанимался:занималась; заготовкой припасов, мои люди отметили некоторые сооружения Плети, которые должны быть уничтожены.$B$BПлан действий таков: я дам тебе 10 брусков моего особого состава, ты отправишься в Чумной лес и оставишь их в сооружениях Плети, помеченных знаком.$B$B<Дымок щелкает пальцами.>$B$BБабах! Все очень просто!', 'Отправляйтесь в Проклятый лес, к северо-западу от Часовни Последней Надежды. Уничтожьте 8 сооружений Плети, отмеченных знаком взрыва, поместив особый состав Дымка внутрь сооружения. Дымок отметил зиккураты и бойни.$B$BРазместив бомбу внутри сооружения, немедленно выбирайтесь наружу и любуйтесь делом рук своих с безопасного расстояния. $B$BАх да, вот еще что, особый состав Дымка – вещество весьма нестабильное.', '', 'Вернитесь к Дымку Лару в Часовню Последней Надежды, что в Восточных Чумных землях.', 'Уничтожено сооружений Плети', '', '', '', 0),
	(6124, 'ruRU', 'Исцеление больных', 'Мази, изготовленной из реагентов, которые ты $gпринес:принесла; мне, $n, хватит на десять доз. Пока я работаю здесь, в деревне, пытаясь изготовить побольше этой мази, я хотела бы, чтобы ты $gпомог:помогла; нам начать исцеление. По всем Темным берегам встречаются больные олени. Используй мазь для исцеления их недуга.$B$BЯ уверена, что Дендрит Блеск Звезд из Лунной поляны захочет поговорить с тобой, когда работа будет закончена. Пожалуйста, передай благодарность жителей Аубердина Кругу Кенария... и позволь мне лично поблагодарить тебя за помощь!', 'Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темных берегах, – это должно их исцелить. По слухам, ареал обитания больных оленей – южнее реки Скалистой и севернее Аубердина, а далее – по всей области, вплоть до южных границ Темных берегов, где начинается Ясеневый лес.', '', 'Вернитесь к Дендриту Блеску Звезд в Ночную Гавань, что на Лунной поляне.', 'Исцелено больных оленей', '', '', '', 0),
	(6129, 'ruRU', 'Исцеление больных', 'Мне удалось сделать десять доз целебной мази. Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотела бы, чтобы ты $gпомог:помогла; нам лечить бедных зверей. По всей северной части Степей бродят больные газели. Исцели их недуг при помощи этой мази.$b$bЯ уверен, что Дендрит Блеск Звезд на Лунной поляне захочет поговорить с тобой, когда ты закончишь. Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!', 'Нанесите мазь исцеления животных на 10 больных газелей, обитающих в северной части Степей, – это должно их вылечить. По слухам, больные газели живут севернее дороги, проходящей через Перекресток с востока на запад.', '', 'Вернитесь к Дендриту Блеску Звезд в Ночную Гавань, что на Лунной поляне.', 'Исцелено больных газелей', '', '', '', 0),
	(6381, 'ruRU', 'Новая жизнь', 'Вот видишь, |3-6($c), хотя эта земля глубоко изранена, круговорот жизни – великая сила. Теперь мы должны внести свой вклад и помочь этой силе. Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине. Но берегись – там, в полумертвых землях, еще встречаются гарпии и злобные элементали огня.$B$B$n, возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы. Круговорот жизни должен продолжаться!', 'Посадите 10 семян Геи в земляные курганы Геи, а затем верните оставшиеся зачарованные семена Геи Таммре в Приют у Солнечного Камня.', '', 'Вернитесь к Таммре Перекати-поле в Приют у Солнечного Камня в Когтистых горах.', 'Посажено семян Геи', '', '', '', 0),
	(6395, 'ruRU', 'Последнее желание Марлы', 'Моя подруга Марла Фиппс жила до чумы со своим мужем Самуэлем, но когда пришла чума, Самуэль погиб... и вступил в ряды Плети. $b$bМарла избежала чумы, но погибла от рук собственного мужа, лишившегося разума. Однако так велика была ее любовь, что последним желанием ее было, чтобы Самуэль был похоронен рядом с ней. $b$bСамуэль Фиппс обитает теперь у разоренного лагеря близ дороги на северо-восток от Похоронного Звона. Убей его и выполни желание Марлы: похорони Самуэля в ее могиле, в первом ряду нашего кладбища.', 'Отнесите останки Самуэля Фиппса на могилу Марлы, а затем вернитесь к новобранцу Элрет.', '', 'Вернитесь к новобранцу Элрет в Похоронный Звон, что в Тирисфальских лесах.', 'Останки Самуэля погребены', '', '', '', 0),
	(6561, 'ruRU', 'Злодейство в Непроглядной Пучине', 'Силы оставили меня. Мне необходима твоя помощь!$B$BВ давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча древнего бога просочилась из-под земли и осквернила священный лунный колодец.$b$bАку\'май, слуга древнего бога, поднялся из глубин.$b$bСлужители культа Сумеречного Молота объединились с нагами в борьбе за эти земли. Ведомые Келрисом, они приносят Аку\'май невинные жертвы.$b$bУбей Келриса и принеси его голову Башане в Громовой Утес, $n.', 'Принесите голову Повелителя сумрака Келриса Башане Рунический Тотем в Громовой Утес.', '', 'Вернитесь к Башане Руническому Тотему в Золотые равнины, что в Мулгоре.', '', '', '', '', 18019),
	(6661, 'ruRU', 'Охота на крыс', 'Эй ты, стой, да? Зарра... За... Зарррработать хочешь? У нас тут большая проблема с крысами и не хватает умелых рук.$B$BЧто ты там болтаешь? Все, что от тебя требуется – взять эту флейту крысолова и сыграть подходящую мелодию. Они пойдут за тобой хоть на край света!$B$BНо это лишнее – ты просто поймай пяток и принеси, они нужны нам живыми.$B$BРрррр...', 'Поймайте 5 подземных крыс, используя Флейту крысолова, и принесите их Монти. Не забудьте вернуть флейту владельцу.', '', 'Вернитесь к Монти в подземный поезд.', 'Поймано крыс', '', '', '', 0),
	(6681, 'ruRU', 'Поместье, Черный Ворон', '$n,$B$BЧерный Ворон очень заинтересовался тобой, $gюный вор:юная воришка;. Мы наблюдали. Тебе не хватает ловкости, но это преходяще.$b$bЕсли ты хочешь стать $gучеником:ученицей; мастера Черного Ворона и членом Лиги убийц, стоит только принести печать Черного Ворона (приложенную к этому письму) в поместье Черный Ворон.$b$bПервым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость.$b$bС уважением,$b$bФарад.', 'Отнесите печать Черного Ворона Фараду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.$b$bНе теряйте бдительности. Поиски поместья – проверка на ловкость.', '', 'Вернитесь к Фараду в Поместье Черного Ворона, что в Предгорьях Хилсбрада.', '', 'Ритуал Хитрости', '', '', 0),
	(7029, 'ruRU', 'Скверна Злоязыкого', 'В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все, до чего может дотянуться. Из-за него умирают растения.$B$bВозьми этот фиал, $n, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.$b$bОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от скверны, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.', 'Наполните лазурный фиал с внутренним покрытием в оранжевом пруду Мародона.$B$BПолейте гнусь-лозу из наполненного фиала, чтобы изгнать ядовитую лозу.$B$BИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников.', '', 'Вернитесь к Варку Боевому Шраму в деревню Гелкис, что в Пустошах.', 'Исцелено растений гнусь-лозы', '', '', '', 0),
	(7041, 'ruRU', 'Скверна Злоязыкого', 'В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все кругом. Из-за него там больше не растут цветы.$B$bВозьми этот фиал, $n, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.$b$bОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от скверны, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.', 'Наполните лазурный фиал с внутренним покрытием в оранжевом пруду Мародона.$B$BПолейте гнусь-лозу из наполненного фиала, чтобы изгнать ядовитую лозу.$B$BИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела.', '', 'Вернитесь к Талендрии в Обугленную долину, что в Когтистых горах.', 'Исцелено растений гнусь-лозы', '', '', '', 0),
	(7081, 'ruRU', 'Кладбища Альтеракской долины', 'Кладбища в Альтеракской долине представляют собой очень большую ценность. И Орда, и Альянс свирепо дерутся за право обладать этими сакральными местами. $GГотов:Готова; ли ты вступить в эту схватку, $n?$B$BЯ хочу, чтобы ты $gзахватил:захватила; кладбище неприятеля. Найди кладбище с вымпелом Орды и вытащи из земли этот вымпел! Вот и все, задание выполнено.$B$BЕсли не сложно, можешь покараулить захваченное кладбище несколько минут, до прибытия наших войск.', 'Захватите кладбище, затем возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.', '', 'Вернитесь к сержанту Даргену Грозовой Вершине на Возвышенность Гэвина в Альтеракских горах.', 'Кладбище захвачено', '', '', '', 0),
	(7082, 'ruRU', 'Кладбища долины Альтерака', 'Линия фронта в Альтеракской долине постоянно изменяется. Мы отступаем и снова отвоевываем территории в смертельной схватке с врагом. Особо яростные сражения идут за кладбища, $n.$B$BЯ приказываю тебе атаковать кладбище Альянса! Найди кладбище со знаменем Альянса в центре и вырви древко из земли!$B$BНа этом задание будет выполнено. Но тебе нужно будет подождать некоторое время, пока не придут наши войска.', 'Захватите кладбище, затем возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.', '', 'Вернитесь к капралу Тике Кровавому Рыку в Альтеракские горы.', 'Кладбище захвачено', '', '', '', 0),
	(7101, 'ruRU', 'Башни и бункеры', 'Башни и бункеры – основные защитные сооружения, так что все они должны быть нашими! Твое следующее задание – захват вражеского бункера.$B$BЗайди в бункер Альянса – над ним развевается их флаг. Внутри ты увидишь знамя. Сними его, и на его месте появится белое знамя Орды. Дело сделано!$B$BБольше ничего не нужно, но если ты немного подождешь и не дашь Альянсу отбить бункер обратно, то он самоуничтожится!', 'Захватите башню врага и возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.', '', 'Вернитесь к капралу Тике Кровавому Рыку в Альтеракские горы.', 'Башня захвачена', '', '', '', 0),
	(7102, 'ruRU', 'Башни и бункеры', 'Башни и бункеры – основные защитные сооружения, так что у нас их должно быть как можно больше! Я приказываю тебе атаковать вражескую башню или бункер в Альтеракской долине.$B$BЗайди в бункер Орды – над ним развевается их флаг. Внутри ты увидишь вымпел. Сними его, и на его месте появится белое знамя Альянса. Дело сделано!$B$BНо на этом задание еще не закончено. Если ты продержишься рядом с башней некоторое время, чтобы ее не захватила Орда, то она разрушится!', 'Уничтожьте вымпел на вражеской башне или бункере и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.', '', 'Вернитесь к сержанту Даргену Грозовой Вершине на Возвышенность Гэвина в Альтеракских горах.', 'Вымпел уничтожен', '', '', '', 0),
	(7122, 'ruRU', 'Захват рудника', 'Рудники в Альтеракской долине – нечто большее, чем обычные сырьевые ресурсы. И Грозовая Вершина, и клан Северного Волка хранят на рудниках свои припасы. Одни – на Железном руднике, другие – на руднике Ледяного Зуба. Неплохо было бы захватить чужие припасы!$B$BЗахвати рудник и возвращайся ко мне. Найди рудник, который никому не принадлежит, и убей того, кто там главный. После этого рудник перейдет к нам, и мы вышлем войска для его охраны.', 'Захватите рудник, который не принадлежит Грозовой Вершине, и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.', '', 'Вернитесь к сержанту Даргену Грозовой Вершине на Возвышенность Гэвина в Альтеракских горах.', 'Рудник захвачен', '', '', '', 0),
	(7124, 'ruRU', 'Захват рудника', 'Битва, разгоревшаяся на землях Альтеракской долины, идет и за рудники – Железный и Ледяного Зуба. Они богаты сырьем, и к тому же их можно использовать для хранения припасов.$B$BПомоги нам, $n! Захвати один из этих рудников, во имя Орды! Отправляйся на рудник, который принадлежит нашим врагам, и убей того, кто там главный. Как только ты захватишь рудник, мы вышлем войска, чтобы взять его под охрану.', 'Захватите рудник и возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.', '', 'Вернитесь к капралу Тике Кровавому Рыку в Альтеракские горы.', 'Рудник захвачен', '', '', '', 0),
	(7301, 'ruRU', 'Свергнутые властители небес', 'Мы взяли их в плен, |3-6($r). Мы захватили командиров звена. В небе разразилась яростная битва, но в итоге они все же уступили! К сожалению, во время контратаки против крепости Северного Волка были сбиты наши лучшие пилоты. Нужно выяснить, что с ними случилось. $b$bОбыщи западную Смотровую башню и крепость Северного Волка. Там они были замечены в последний раз. Как можно тщательней осмотри эти районы.', 'Отправляйтесь в крепость Северного Волка и поищите командиров звена Слидора, Змейера и Ичмана. Вернитесь с отчетом к командиру Даффи.', '', 'Вернитесь к командиру Даффи в Альтеракскую долину.', 'Ичмен найден', 'Змейер найден', 'Слидор найден', '', 0),
	(7302, 'ruRU', 'Свергнутые властители небес', 'Наша воздушная поддержка в полном беспорядке, $n. Командиров звена сбили на вражеской территории. Ты $gдолжен:должна; узнать, что с ними стало, чтобы мы могли попытаться их спасти! $b$bСмуггла в последний раз видели над укрытием Ледяного Крыла. Боевую виверну Мааши заметили у лесопилки Грозовой Вершины. Маэстр... кто-то видел, как этот пустоголовый идиот разбился возле северного оплота Дун Болдара. $b$bЭто вся информация, что у меня есть. За дело! Как следует прочеши указанные районы.', 'Выясните, что стало с командирами звена Гусом, Джезтором и Маэстром. Вернитесь с отчетом к командиру Мулфорту.', '', 'Вернитесь к командиру Мулфорту в Деревню Северного Волка, что в Альтеракской долине.', 'Гус найден', 'Джезтор найден', 'Найдите Маэстра', '', 0),
	(7629, 'ruRU', 'Доставка беса', 'Для подготовки пергамента Морзула осталось сделать только одно – напитать бумагу зоротианской звездной пылью. И... боюсь, здесь этого не сделать. Мне не хватит оборудования!$b$bВпрочем, я знаю об одной лаборатории, где есть все необходимое. Она находится в Некроситете, на острове Каэр Дарроу, в Чумных землях.$b$bЯ туда отправиться не смогу, но у меня есть идея. Возьми эту бутылку. В ней сидит довольно умный бес. Выпусти его в алхимической лаборатории, и он напитает пергамент звездной пылью.', 'Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу.', '', 'Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.', 'Пергамент создан', '', '', '', 0),
	(7790, 'ruRU', 'Написанное слово', 'Вот нечто неожиданное для тебя...$b$b$b', '', '', 'Поговорите с Джонатаном Лекрафтом.', 'Уничтожьте лесопилку клана Песни Войны', '', '', '', 0),
	(8105, 'ruRU', 'Битва за Низину Арати', '$n, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $b$bНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $b$bКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.', 'Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.', '', 'Вернитесь к фельдмаршалу Освету на Опорный пункт, что на Нагорье Арати.', 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на ферму совершено', 0),
	(8120, 'ruRU', 'Битва за Низину Арати', 'Как ты, конечно, $Gслышал:слышала;, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей!$B$BОтправляйся в Низину Арати и напади на рудник, лесопилку, кузницу и стойла. Сорви с флагштоков вражеские знамена, заявив о правах Орды на эти территории.$B$BИди, $n. Доложи мне, когда выполнишь задание.', 'Нападите на рудник, лесопилку, кузницу и стойла в Низине Арати и возвращайтесь к повелительнице смерти Двайр в Павший Молот.', '', 'Вернитесь к повелительнице смерти Двайр к Восточному кругу Обуздания, что на Нагорье Арати.', 'Нападение на рудник совершено', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на стойла совершено', 0),
	(8166, 'ruRU', 'Битва за Низину Арати', '$n, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $b$bНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $b$bКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.', 'Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.', '', 'Вернитесь к фельдмаршалу Освету на Опорный пункт, что на Нагорье Арати.', 'Рудник захвачен', 'Нападение на лесопилку совершено', 'Нападение на кузницу совершено', 'Нападение на ферму совершено', 0),
